// ============================================================
// MiniMax 图片生成
// ============================================================
async function generateImage(slug, topic, apiKey) {
  const imageDir = IMAGES_DIR
  const filename = `${slug}.jpg`
  const filepath = path.join(imageDir, filename)

  if (fs.existsSync(filepath)) {
    console.log(`  🖼️ 图片已存在: ${filename}`)
    return `/images/articles/${filename}`
  }

  if (!apiKey) {
    // 用占位图片路径，实际由MiniMax生成
    console.log(`  ⚠️ 无API Key，跳过图片生成`)
    return `/images/articles/avr-default.jpg`
  }

  return new Promise((resolve, reject) => {
    const prompt = `Professional technical illustration for an article about: ${topic}. Clean, modern infographic style with blue and white color scheme. No text. Suitable for SEO article hero image.`
    const body = JSON.stringify({
      model: 'MiniMax-image-01',
      prompt,
      width: 1200,
      height: 630,
      number: 1,
      output_format: 'jpeg',
      style: 'natural'
    })

    const options = {
      hostname: 'api.minimax.io',
      path: '/v1/image_generation',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey}`
      }
    }

    const req = https.request(options, (res) => {
      let data = ''
      res.on('data', chunk => data += chunk)
      res.on('end', () => {
        try {
          const result = JSON.parse(data)
          if (result.data && result.data[0] && result.data[0].url) {
            // 下载图片
            const imgReq = https.get(result.data[0].url, (imgRes) => {
              const file = fs.createWriteStream(filepath)
              imgRes.pipe(file)
              file.on('finish', () => resolve(`/images/articles/${filename}`))
            })
            imgReq.on('error', () => resolve('/images/articles/avr-default.jpg'))
          } else {
            console.log(`  ⚠️ 图片生成失败: ${JSON.stringify(result).substring(0, 100)}`)
            resolve('/images/articles/avr-default.jpg')
          }
        } catch (e) {
          resolve('/images/articles/avr-default.jpg')
        }
      })
    })
    req.on('error', () => resolve('/images/articles/avr-default.jpg'))
    req.write(body)
    req.end()
  })
}

