// ============================================================
// 主函数：生成一天的文章
// ============================================================
async function generateDayArticles(startIndex, numArticles = 10) {
  console.log(`\n📝 开始生成文章 (起始索引: ${startIndex}, 数量: ${numArticles})`)
  
  // 计算日期：从今天开始 + startIndex/10 天
  const today = new Date()
  const daysOffset = Math.floor(startIndex / 10)
  const dateStr = new Date(today.getTime() + daysOffset * 24 * 60 * 60 * 1000)
    .toISOString().split('T')[0]

  const apiKey = process.env.MINIMAX_API_KEY || ''

  const results = []
  for (let i = 0; i < numArticles && (startIndex + i) < ARTICLE_THEMES.length; i++) {
    const theme = ARTICLE_THEMES[startIndex + i]
    console.log(`\n  📄 生成文章 ${i + 1}/${numArticles}: ${theme.slug}`)

    // 生成图片
    const imageUrl = await generateImage(theme.slug, theme.title.en, apiKey)
    console.log(`  🖼️ 图片: ${imageUrl}`)

    // 生成JSON
    const article = generateArticleJSON(theme, imageUrl, dateStr)
    const filepath = path.join(ARTICLES_DIR, `${theme.slug}.json`)
    fs.writeFileSync(filepath, JSON.stringify(article, null, 2, ensureASCII))
    console.log(`  ✅ JSON已写入: ${theme.slug}.json`)
    results.push(theme.slug)
  }

  console.log(`\n✅ 完成！生成了 ${results.length} 篇文章`)
  return results
}

// ============================================================
// 辅助：确保ASCII（兼容emoji问题）
// ============================================================
function ensureASCII(key, value) {
  return value
}

// ============================================================
// CLI入口
// ============================================================
if (require.main === module) {
  // argv[2] = startIndex (0-300), argv[3] = numArticles (default 10)
  const startIndex = parseInt(process.argv[2] || '0')
  const numArticles = parseInt(process.argv[3] || '10')

  generateDayArticles(startIndex, numArticles)
    .then(slugs => {
      console.log('\n生成的文章:', slugs.join(', '))
    })
    .catch(console.error)
}